/** Returns DS with Czech labels when LANG is 'cs' (DS is not modified). */
export function localizeSample(id: string, ds: Dataset, lang: string): Dataset {
  const cs = SAMPLES_CS[id];
  if (lang !== 'cs' || !cs) return ds;
  const columns = ds.columns.map((col, i) => {
    const map = cs.cells?.[ds.variables[i].name];
    return map ? col.map((c) => (typeof c === 'string' ? (map[c.trim()] ?? c) : c)) : col;
  });
  const variables = ds.variables.map((v) => {
    const tr = cs.vars[v.name];
    if (!tr) return v;
    return {
      ...v,
      label: tr.label,
      valueLabels: v.valueLabels.map((l) => ({ ...l, label: tr.values?.[String(l.value).trim()] ?? l.label })),
    };
  });
  return { ...ds, variables, columns, fileLabel: cs.fileLabel, documents: cs.documents ?? ds.documents };
}
